    private function upgradeKnownStarter(string $slug, string $starterBody, array $replacement): void
    {
        $page = ContentPage::query()->where('slug', $slug)->first();

        if ($page && $page->translation('body', 'en') === $starterBody) {
            $page->update($replacement);
        }
    }

