            'summary' => $summary, 'body' => $body, 'meta_title' => $metaTitle,
            'meta_description' => $metaDescription, 'primary_query' => $primaryQuery,
            'search_intent' => 'commercial', 'robots_directive' => config('website.discovery.default_robots'),
            'sitemap_included' => true, 'sitemap_priority' => 0.9, 'sitemap_change_frequency' => 'monthly',
            'metadata' => array_filter(['service' => $profile, 'faqs' => $faqs, 'related_slugs' => $relatedSlugs, 'cta' => $cta], fn (mixed $value): bool => $value !== null),
            'status' => 'published', 'featured' => true, 'sort_order' => $sortOrder, 'published_at' => now(),
        ];
    }

    private function serviceProfile(array $engagement, array $delivery, array $handover, array $capabilities): array
    {
        return ['engagement' => $engagement, 'delivery' => $delivery, 'handover' => $handover, 'capabilities' => $this->capabilities($capabilities)];
    }

    private function capabilities(array $items): array
    {
        return array_map(fn (array $item): array => ['en' => $item[0], 'fa' => $item[1], 'ps' => $item[2]], $items);
    }

    private function faq(string $enQuestion, string $enAnswer, string $faQuestion, string $faAnswer, string $psQuestion, string $psAnswer): array
    {
        return ['question' => ['en' => $enQuestion, 'fa' => $faQuestion, 'ps' => $psQuestion], 'answer' => ['en' => $enAnswer, 'fa' => $faAnswer, 'ps' => $psAnswer]];
    }
}
